<section class="page-head"><p class="eyebrow"><?= e($country->name()) ?> · <?= e($country->currencyCode()) ?></p><h1>Investment opportunities</h1><p>Company information and platform-configured offering terms for your investment region.</p></section>
<form class="catalogue-filters card" method="get" action="<?= e(route('companies.index')) ?>"><label>Search <input name="q" value="<?= e($filters['q']) ?>" placeholder="Company, ticker, industry or exchange"></label><label>Industry <select name="industry"><option value="">All industries</option><?php foreach($industries as $item):?><option value="<?= e($item['industry']) ?>"<?= $filters['industry']===$item['industry']?' selected':'' ?>><?= e($item['industry']) ?></option><?php endforeach;?></select></label><label>Exchange <select name="exchange"><option value="">All exchanges</option><?php foreach($exchanges as $item):?><option value="<?= e($item['stock_exchange']) ?>"<?= $filters['exchange']===$item['stock_exchange']?' selected':'' ?>><?= e($item['stock_exchange']) ?></option><?php endforeach;?></select></label><label>Sort <select name="sort"><?php foreach(['featured'=>'Featured','newest'=>'Newest','name'=>'Name','price_low'=>'Price: low to high','price_high'=>'Price: high to low','projected_return'=>'Projected return','duration'=>'Duration'] as $key=>$label):?><option value="<?= e($key) ?>"<?= $filters['sort']===$key?' selected':'' ?>><?= e($label) ?></option><?php endforeach;?></select></label><button class="button">Apply filters</button></form>
<?php if(!$companies):?><section class="section"><?php $message='No active investments are available for this Country Pack yet.';require BASE_PATH.'/resources/views/components/empty-state.php';?></section><?php else:?><section class="company-grid"><?php foreach($companies as $company):?><article class="company-card card"><div class="company-mark" aria-hidden="true"><?= e(strtoupper(substr($company['display_name'],0,1))) ?></div><div><p class="eyebrow"><?= e($company['ticker']) ?> · <?= e($company['stock_exchange']) ?></p><h2><?= e($company['display_name']) ?></h2><p><?= e($company['industry']?:$company['sector']?:'Listed company') ?></p></div><?php if($company['offering_featured']):?><span class="badge">Featured</span><?php endif;?><dl><div><dt>Investment price</dt><dd><?= e(country_money(new \App\Support\Money((int)$company['share_price_minor'],$company['currency_code']))) ?></dd></div><div><dt>Projected term</dt><dd><?= e($company['projected_profit_value']) ?><?= $company['profit_type']==='PERCENTAGE'?'%':' fixed' ?> · <?= e($company['duration_value'].' '.strtolower($company['duration_unit'])) ?></dd></div></dl><a class="button button-small" href="<?= e(route('companies.show',['company'=>$company['public_id']])) ?>">View opportunity</a></article><?php endforeach;?></section><?php if($pagination->pages()>1):?><nav class="pagination" aria-label="Companies pages"><?php for($i=1;$i<=$pagination->pages();$i++):$query=array_filter([...$filters,'page'=>$i],fn($v)=>$v!=='');?><a<?= $i===$pagination->page?' aria-current="page"':'' ?> href="<?= e(route('companies.index').'?'.http_build_query($query)) ?>"><?= $i ?></a><?php endfor;?></nav><?php endif;?><?php endif;?>
